// Encode function implementations
uint32_t encode_abs_z_p_z_m(uint32_t Zd, uint32_t Zn, uint32_t Pg, uint32_t size) {
    SveEncoding insn = {};
    insn.abs_zpzm.Zd = Zd;
    insn.abs_zpzm.Zn = Zn;
    insn.abs_zpzm.Pg = Pg;
    insn.abs_zpzm._unnamed_5 = 0b101;
    insn.abs_zpzm.opc = 0b110;
    insn.abs_zpzm._unnamed_4 = 0b0;
    insn.abs_zpzm.M = 0b1;
    insn.abs_zpzm._unnamed_3 = 0b0;
    insn.abs_zpzm.size = size;
    insn.abs_zpzm._unnamed_2 = 0b0;
    insn.abs_zpzm._unnamed_1 = 0b0010;
    insn.abs_zpzm._unnamed_0 = 0b000;
    return insn.raw;
}

